-- Whoever sells or keeps the books reads prices; an owner, an accountant or a sales manager sets
-- them. The warehouse, recovery and payroll roles have no business with prices.
CREATE POLICY price_lists_select ON public.price_lists FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson'));
--> statement-breakpoint
CREATE POLICY price_lists_insert ON public.price_lists FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager')
    AND created_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
